∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_4} [inst : AddCommMonoid M] {s : Finset ι} {t : Finset κ}
  [inst_1 : DecidableEq κ] {g : ι → κ},
  (∀ i ∈ s, g i ∈ t) → ∀ (f : ι → M), ∑ j ∈ t, ∑ i ∈ s with g i = j, f i = ∑ i ∈ s, f i

∀ {R : Type u_1} {M : Type u_4} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {ι : Sort u_10}
  {κ : ι → Sort u_9} (s : (i : ι) → κ i → Set M),
  Submodule.span R (⋃ i, ⋃ j, s i j) = ⨆ i, ⨆ j, Submodule.span R (s i j)

∀ {K : Type u_1} {V : Type u_2} [inst : Field K] [inst_1 : AddCommGroup V] [inst_2 : Module K V] [Finite V] {r : ℕ},
  r ≤ Module.finrank K V →
    Nat.card { W // Module.finrank K ↥W = r } = Nat.card { Φ // Module.finrank K ↥Φ = Module.finrank K V - r }

∀ {n d p r : ℕ} [NeZero n] [inst : Fact (Nat.Prime p)],
  p ∣ n →
    Nat.card { H // (∀ x ∈ H, p • x = 0) ∧ Nat.card ↥H = p ^ r } = Nat.card { U // Module.finrank (ZMod p) ↥U = r }

